"use client";
import React, { useState } from "react";
import { ShieldCheck, Cpu, Layers, Zap, Info, Activity, Beaker, Radio } from "lucide-react";

const qualityMatrix = {
  footwear: [
    { 
      id: "surplus", 
      name: "Factory Surplus", 
      tier: "Lvl 00: Genuine", 
      accuracy: "100%", 
      detail: "Official retail inventory. These are 'backdoor' pairs or overproduction from licensed contracts. 100% authentic anatomy.", 
      tech: ["Retail Box", "NFC Verified", "Official Batch"] 
    },
    { 
      id: "og", 
      name: "OG / LJR Batch", 
      tier: "Lvl 01: Top-Spec", 
      accuracy: "99%", 
      detail: "The highest replica tier. Uses identical material chemistry (PK 4.0/LJR). Often indistinguishable from retail even under blacklight.", 
      tech: ["Prime Materials", "Correct Weight", "UV Passed"] 
    },
    { 
      id: "ua", 
      name: "UA (Unauthorized)", 
      tier: "Lvl 02: High-Spec", 
      accuracy: "97%", 
      detail: "Parallel production using original blueprints. High-grade construction but may have minor QC variances in stitching density.", 
      tech: ["Original Molds", "Real Leather"] 
    },
    { 
      id: "semi-ua", 
      name: "Semi-UA", 
      tier: "Lvl 03: Performance", 
      accuracy: "90%", 
      detail: "Matches the silhouette and external texture perfectly. Internal cushioning uses high-density foam instead of official tech (Zoom/Air).", 
      tech: ["High-End Synth", "Retail Shape"] 
    },
    { 
      id: "7a", 
      name: "7A Grade", 
      tier: "Lvl 04: Visual 1:1", 
      accuracy: "82%", 
      detail: "The 'Street Standard.' Looks perfect on-foot. Uses mid-grade synthetics that look like leather but age differently over time.", 
      tech: ["Visual Match", "Daily Durable"] 
    },
    { 
      id: "6a", 
      name: "6A Grade", 
      tier: "Lvl 05: Standard", 
      accuracy: "72%", 
      detail: "Common market grade. Correct colors and branding, but uses standard factory materials. Noticeable weight difference to experts.", 
      tech: ["Standard Build", "Budget Conscious"] 
    },
    { 
      id: "5a", 
      name: "5A Grade", 
      tier: "Lvl 06: Budget", 
      accuracy: "60%", 
      detail: "Entry-level silhouette. Focuses on the look from a distance. Materials are basic and longevity is limited.", 
      tech: ["Economy Tech", "Color Accurate"] 
    },
  ],
  watches: [
    { 
      id: "superclone", 
      name: "Super Clone (Clean/VSF)", 
      tier: "Lvl 01: Master", 
      accuracy: "99%", 
      detail: "Uses 904L oystersteel and bespoke cloned movements. The 'sweep' of the hand matches the official BPH (Beats Per Hour).", 
      tech: ["904L Steel", "Clone Movement"] 
    },
    { 
      id: "aaa", 
      name: "AAA+ Grade", 
      tier: "Lvl 02: Reliable", 
      accuracy: "85%", 
      detail: "Automatic Miyota movements. Heavy-duty build but uses 316L steel instead of 904L.", 
      tech: ["Sapphire Glass", "Miyota Auto"] 
    },
  ]
};

export default function QualityProtocolPage() {
  const [activeCat, setActiveCat] = useState<keyof typeof qualityMatrix>("footwear");

  return (
    <div className="bg-[#050505] text-[#f0f0f0] min-h-screen pb-32 selection:bg-brand selection:text-black font-sans">
      
      {/* 1. NEURAL HEADER */}
      <header className="pt-24 pb-16 px-6 max-w-7xl mx-auto flex flex-col items-center text-center">
        <div className="flex items-center gap-2 mb-8 px-4 py-1.5 rounded-full bg-brand/10 border border-brand/20">
          <Radio size={12} className="text-brand animate-pulse" />
          <span className="text-[9px] font-black uppercase tracking-[0.5em] text-brand">2026 Verification Standards</span>
        </div>
        <h1 className="text-7xl md:text-[9vw] font-black uppercase italic tracking-tighter leading-[0.75] mb-10">
          Quality <br /> <span className="opacity-10 italic tracking-widest">Sectors</span>
        </h1>
        <p className="max-w-2xl text-[10px] font-bold uppercase leading-relaxed opacity-40 tracking-[0.2em] italic">
          Total Transparency. We dissect the global manufacturing chain to provide a surgical breakdown of every tier available in the current market.
        </p>
      </header>

      {/* 2. CATEGORY SELECTOR */}
      <nav className="flex justify-center mb-24 px-6">
        <div className="bg-[#0f0f0f] p-2 rounded-full border border-white/5 flex gap-2 shadow-2xl overflow-x-auto">
          {Object.keys(qualityMatrix).map((cat) => (
            <button
              key={cat}
              onClick={() => setActiveCat(cat as any)}
              className={`px-12 py-4 rounded-full text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                activeCat === cat ? "bg-brand text-black" : "opacity-30 hover:opacity-100"
              }`}
            >
              {cat}
            </button>
          ))}
        </div>
      </nav>

      {/* 3. THE PROTOCOL GRID */}
      <main className="max-w-7xl mx-auto px-6 grid grid-cols-1 gap-4">
        {qualityMatrix[activeCat].map((item, i) => (
          <div 
            key={item.id}
            className={`group relative bg-[#0a0a0a] border border-white/5 rounded-[3rem] p-8 md:p-12 hover:border-brand/40 transition-all duration-700 flex flex-col lg:flex-row gap-12 items-center ${
              item.id === 'surplus' ? 'border-brand/30 bg-gradient-to-r from-[#0a0a0a] to-brand/5' : ''
            }`}
          >
            {/* Accuracy Indicator */}
            <div className="shrink-0 relative">
               <div className="h-28 w-28 rounded-full border-2 border-white/5 flex items-center justify-center relative overflow-hidden">
                  <div 
                    className="absolute bottom-0 left-0 w-full bg-brand/20 transition-all duration-1000" 
                    style={{ height: item.accuracy }}
                  />
                  <span className="relative z-10 text-2xl font-black italic">{item.accuracy}</span>
               </div>
               <p className="text-[7px] font-black uppercase tracking-[0.3em] mt-4 text-center opacity-30">Accuracy Metric</p>
            </div>

            {/* Content Body */}
            <div className="flex-1 space-y-6 text-center lg:text-left">
              <div className="space-y-2">
                <div className="flex flex-wrap justify-center lg:justify-start gap-4 mb-2">
                  <span className="text-brand text-[8px] font-black uppercase tracking-[0.4em] border border-brand/30 px-3 py-1 rounded-full bg-brand/5">
                    {item.tier}
                  </span>
                  {item.id === 'surplus' && (
                    <span className="text-white text-[8px] font-black uppercase tracking-[0.4em] border border-white/30 px-3 py-1 rounded-full bg-white/10">
                      Authentic
                    </span>
                  )}
                </div>
                <h3 className="text-4xl md:text-6xl font-black uppercase italic tracking-tighter">{item.name}</h3>
              </div>
              <p className="text-[13px] font-medium opacity-50 max-w-2xl leading-relaxed italic uppercase">
                {item.detail}
              </p>
            </div>

            {/* Technical Verification List */}
            <div className="grid grid-cols-1 gap-2 w-full lg:w-64 shrink-0">
              <p className="text-[8px] font-black uppercase tracking-widest opacity-20 mb-2">Protocol Verified</p>
              {item.tech.map((t) => (
                <div key={t} className="flex items-center justify-between px-5 py-3 bg-white/5 rounded-2xl border border-white/5 group-hover:bg-brand/10 transition-colors">
                  <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{t}</span>
                  <ShieldCheck size={12} className="text-brand" />
                </div>
              ))}
            </div>
          </div>
        ))}
      </main>

      {/* 4. THE 2026 SURPLUS MANIFESTO */}
      <section className="max-w-7xl mx-auto px-6 mt-24">
        <div className="bg-brand text-black rounded-[4rem] p-12 md:p-24 relative overflow-hidden group">
          <div className="absolute -right-20 -bottom-20 opacity-10 group-hover:scale-110 transition-transform duration-1000">
             <Cpu size={500} strokeWidth={1} />
          </div>
          <div className="relative z-10 grid grid-cols-1 lg:grid-cols-2 gap-20 items-center">
            <h2 className="text-6xl md:text-9xl font-black uppercase italic tracking-tighter leading-[0.8]">
              Surplus <br /> vs <br /> OG
            </h2>
            <div className="space-y-8">
              <div className="space-y-4">
                <h4 className="text-xl font-black uppercase italic">The Definitive Distinction</h4>
                <p className="text-sm font-bold uppercase leading-tight opacity-70">
                  <span className="underline decoration-2">Surplus</span> is the official item, rejected or overstocked. <br />
                  <span className="underline decoration-2">OG Batch</span> is a high-precision reconstruction that matches 99% of the retail DNA.
                </p>
              </div>
              <div className="grid grid-cols-2 gap-8 pt-8 border-t border-black/10">
                <div>
                  <p className="text-[9px] font-black uppercase tracking-widest opacity-40 mb-2">Retail Logic</p>
                  <p className="text-sm font-black italic uppercase">100% Authorized Materials</p>
                </div>
                <div>
                  <p className="text-[9px] font-black uppercase tracking-widest opacity-40 mb-2">Market Logic</p>
                  <p className="text-sm font-black italic uppercase">Precision Engineering</p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* 5. LAB DISCLAIMER */}
      <footer className="mt-24 px-6 max-w-4xl mx-auto text-center space-y-4">
         <Info size={24} className="mx-auto text-brand opacity-50" />
         <p className="text-[9px] font-black uppercase tracking-[0.3em] opacity-30 leading-loose">
           Note: Quality tiers are market-defined categories based on factory origin (H12, LJR, PK, Clean). <br />
           Specifications are verified through our 2026 Lab Protocol. 
         </p>
      </footer>
    </div>
  );
}